/* Full conjugation tables (Verb reference), the Rules page ("how to form it" + simple rules),
   and the "How to form it" box in Practice. Loaded after voice-and-letters.js. */

// T: bilingual HTML for longer text (English only / Czech + English below / Czech only). Inputs are trusted constants.
const T=(cz,en)=>isEn()?en:isEasy()?cz+'<span class="en">'+en+'</span>':cz;
const tx=pair=>T(pair[0],pair[1]);
const PERSONS=[['já','I'],['ty','you (informal)'],['on / ona / ono','he / she / it'],['my','we'],['vy','you (plural / polite)'],['oni / ony','they']];
const KEYS=['1sg','2sg','3sg','1pl','2pl','3pl'];
let refTense='Present';

/* ---------- building the forms ---------- */
function variants(s){return (s||'').split(',').map(x=>x.trim()).filter(Boolean);}
function fmtVariant(x){const coll=/\(coll\.\)/.test(x);const t=x.replace(/\s*\(coll\.\)/,'').replace(/\s+/g,' ');return esc(t)+(coll?' <small class="coll">'+esc(B('hovorově','spoken'))+'</small>':'');}
function fmt(s){return s==='—'?'—':variants(s).map(fmtVariant).join(' / ');}
function splitRefl(v,form){const p=reflex(v),f=form.trim();return p&&f.endsWith(' '+p)?[f.slice(0,-p.length-1),p]:[f,p];}
function pastParts(v){const [m,p]=splitRefl(v,first(v.past_m));const [f]=splitRefl(v,first(v.past_f));const [pl]=splitRefl(v,first(v.past_pl_m));const stem=f.endsWith('a')?f.slice(0,-1):f;return {m,f,n:stem+'o',pl,fpl:stem+'y',p,P:p?' '+p:''};}
function genderNote(x,aux){const P=x.P;
 return B(`Jak číst lomítko: první tvar je pro muže (${x.m}${P}), druhý pro ženu (${x.f}${P}). U on / ona / ono je třetí tvar pro střední rod, např. dítě (${x.n}${P}). U oni / ony: ${x.pl}${P} = muži nebo smíšená skupina, ${x.fpl}${P} = jen ženy. Zdvořilé vy k jedné osobě: ${x.m} ${aux}${P} (muž) / ${x.f} ${aux}${P} (žena).`,
  `How to read the slash: the first form is for a man (${x.m}${P}), the second for a woman (${x.f}${P}). For on / ona / ono the third form is for neuter nouns, e.g. dítě, a child (${x.n}${P}). For oni / ony: ${x.pl}${P} = men or a mixed group, ${x.fpl}${P} = women only. Polite vy to one person: ${x.m} ${aux}${P} (to a man) / ${x.f} ${aux}${P} (to a woman).`);}
function conj(v,tense){
 const rows=[],notes=[];const perf=v.aspect==='perfective';
 if(tense==='Present'){
  if(perf){notes.push(B(`${v.verb} je dokonavé, a proto nemá přítomný čas. Jeho „přítomné“ tvary znamenají budoucnost (viz Budoucí čas).`,`${v.verb} is perfective, so it has no present tense. Its “present” forms mean future (see Future).`)+(v.aspect_partner?' '+B('Pro přítomnost použijte','For the present use')+' '+v.aspect_partner+'.':''));return {rows,notes};}
  KEYS.forEach((k,i)=>rows.push([...PERSONS[i],fmt(v[k])]));
 }else if(tense==='Past'){
  const x=pastParts(v);
  rows.push([...PERSONS[0],esc(`${x.m} / ${x.f} jsem${x.P}`)]);
  rows.push([...PERSONS[1],esc(x.p?`${x.m} / ${x.f} ${x.p==='se'?'ses':'sis'}`:`${x.m} / ${x.f} jsi`)]);
  rows.push([...PERSONS[2],esc(`${x.m} / ${x.f} / ${x.n}${x.P}`)]);
  rows.push([...PERSONS[3],esc(`${x.pl} jsme${x.P}`)]);
  rows.push([...PERSONS[4],esc(`${x.pl} jste${x.P}`)]);
  rows.push([...PERSONS[5],esc(`${x.pl} / ${x.fpl}${x.P}`)]);
  notes.push(genderNote(x,'jste'));
 }else if(tense==='Future'){
  if(perf){KEYS.forEach((k,i)=>rows.push([...PERSONS[i],fmt(v[k])]));notes.push(B('Dokonavé sloveso: tvary jako v přítomném čase, ale význam je budoucí. Nepoužívejte budu.','Perfective verb: the forms look like the present, but the meaning is future. Do not use budu.'));}
  else{const p=reflex(v),base=p?v.verb.slice(0,-3):v.verb,motion=futureMotion[v.verb];
   KEYS.forEach((k,i)=>rows.push([...PERSONS[i],esc(motion?motion[i]+(p?' '+p:''):v.verb==='být'?futureAux[k]:`${futureAux[k]} ${p?p+' ':''}${base}`)]));
   notes.push(motion?B(`${v.verb} má zvláštní budoucí tvar (${motion[0]}), ne „budu ${v.verb}“.`,`${v.verb} has a special future (${motion[0]}), not “budu ${v.verb}”.`):v.verb==='být'?B('Budoucí čas slovesa být je budu, budeš…','The future of být is budu, budeš…'):B('Nedokonavé sloveso: budu, budeš, bude… + infinitiv.','Imperfective verb: budu, budeš, bude… + infinitive.'));}
 }else if(tense==='Conditional'){
  const x=pastParts(v);
  rows.push([...PERSONS[0],esc(`${x.m} / ${x.f} bych${x.P}`)]);
  rows.push([...PERSONS[1],esc(x.p?`${x.m} / ${x.f} by ${x.p==='se'?'ses':'sis'}`:`${x.m} / ${x.f} bys`)]);
  rows.push([...PERSONS[2],esc(`${x.m} / ${x.f} / ${x.n} by${x.P}`)]);
  rows.push([...PERSONS[3],esc(`${x.pl} bychom${x.P}`)]);
  rows.push([...PERSONS[4],esc(`${x.pl} byste${x.P}`)]);
  rows.push([...PERSONS[5],esc(`${x.pl} / ${x.fpl} by${x.P}`)]);
  notes.push(genderNote(x,'byste'));
 }else{ // Imperative
  if(v.imp_sg==='—'){notes.push(B(`${v.verb} nemá rozkazovací způsob.`,`${v.verb} has no imperative.`));return {rows,notes};}
  const my=variants(v.imp_pl).map(x=>{const w=x.split(' ');if(w[0].endsWith('te'))w[0]=w[0].slice(0,-2)+'me';return w.join(' ');});const ind=variants(v['1pl']);const myF=my.length>1?my.filter(x=>!ind.includes(x)):my;
  rows.push(['ty',PERSONS[1][1],fmt(v.imp_sg)]);rows.push(['my','let’s',fmt(myF.join(', '))]);rows.push(['vy',PERSONS[4][1],fmt(v.imp_pl)]);
  const partner=v.aspect==='perfective'&&verbs.find(x=>x.verb===v.aspect_partner);const neg=partner&&partner.imp_sg!=='—'?first(partner.imp_sg):'';
  if(neg)notes.push(B(`Zápor: ne + nedokonavé sloveso → ne${neg}${partner?` (od ${partner.verb})`:''}.`,`Negative: ne + the imperfective verb → ne${neg}${partner?` (from ${partner.verb})`:''}.`));
 }
 return {rows,notes};
}
function conjTable(v,tense){const {rows,notes}=conj(v,tense);
 return (rows.length?`<table class="conj"><tbody>${rows.map(([cz,en,form])=>`<tr><th>${esc(cz)}${isEasy()?` <small>${esc(en)}</small>`:''}</th><td>${form}</td></tr>`).join('')}</tbody></table>`:'')+
  notes.map(n=>`<p class="conj-note">${esc(n)}</p>`).join('')+`<p class="formula-line"><span>${esc(B('Jak se tvoří','How it is formed'))}:</span> ${tx(FORM[tense].formula)}</p>`;}
function tenseOptions(sel){const o=k=>`<option value="${k}"${k===sel?' selected':''}>${esc(LV(k))}</option>`;return `<optgroup label="${esc(B('Časy','Tenses'))}">${['Present','Past','Future'].map(o).join('')}</optgroup><optgroup label="${esc(B('Způsoby','Moods'))}">${['Conditional','Imperative'].map(o).join('')}</optgroup>`;}

/* ---------- Verb reference ---------- */
function fillEntry(d){const v=verbs.find(x=>x.verb===d.dataset.verb);if(!v)return;const body=d.querySelector('.entry-body');
 body.innerHTML=`<label class="tense-pick">${esc(B('Čas / způsob','Tense / mood'))} <select>${tenseOptions(refTense)}</select></label><div class="conj-out">${conjTable(v,refTense)}</div>${verbInfo(v)}`;
 body.querySelector('select').onchange=e=>{refTense=e.target.value;body.querySelector('.conj-out').innerHTML=conjTable(v,refTense);};}
renderDictionary=function(){const query=clean($('verb-search').value);const lvl=$('ref-level').value;const na=x=>x.normalize('NFD').replace(/[\u0300-\u036f]/g,'');const plain=query===na(query);const key=x=>plain?na(clean(x)):clean(x);
 const matches=verbs.filter(v=>(lvl==='all'||v.level===lvl)&&(key(v.verb).includes(query)||(isEasy()&&clean(v.english).includes(query))));const LO={A:0,B:1,C:2};
 const rank=v=>{if(!query)return 0;const k=key(v.verb),b=k.replace(/ (se|si)$/,'');return k===query||b===query?0:k.startsWith(query)?1:2;};
 matches.sort((x,y)=>rank(x)-rank(y)||(LO[x.level]??0)-(LO[y.level]??0)||x.verb.localeCompare(y.verb,'cs'));
 const intro=`<p class="muted ref-intro">${esc(B('Klikněte na sloveso a vyberte čas nebo způsob — uvidíte všechny tvary.','Click a verb, then choose a tense or mood to see all its forms.'))} ${matches.length} ${esc(matches.length===1?B('sloveso','verb'):B('sloves','verbs'))}${matches.length>150&&!query?' · '+esc(B('zobrazeno prvních 150 — hledejte nebo zvolte úroveň','showing the first 150 — search or choose a level')):''}</p>`;
 $('dictionary-results').innerHTML=intro+(matches.length?matches.slice(0,query?400:150).map(v=>`<details class="verb-entry" data-verb="${esc(v.verb)}"><summary><span class="lvl ${esc(v.level||'A')}">${esc(v.level||'A')}</span><strong>${esc(v.verb)}</strong>${isEasy()?` <span class="gloss">${esc(v.english)}</span> <span class="chip">${esc(B(v.aspect==='both'?'obouvidové':v.aspect==='perfective'?'dokonavé':'nedokonavé',v.aspect==='both'?'both aspects':v.aspect))}</span>`:''}</summary><div class="entry-body"></div></details>`).join(''):'<p>'+esc(B('Sloveso v databázi není.','This verb is not in the database.'))+'</p>');
 $('dictionary-results').querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)fillEntry(d);}));};

/* ---------- How each tense / mood is formed ---------- */
const FORM={
 Present:{title:['Přítomný čas','Present tense'],formula:['infinitiv → skupina → koncovky','infinitive → group → endings'],
  steps:[['Podívejte se na konec infinitivu: -at → 1. skupina (dělám), -et/-ět/-it → 2. skupina (rozumím, mluvím), -ovat → 3. skupina (pracuju), -ít, -íst, -ýt… → 4. skupina (piju, čtu).','Look at the end of the infinitive: -at → group 1 (dělám), -et/-ět/-it → group 2 (rozumím, mluvím), -ovat → group 3 (pracuju), -ít, -íst, -ýt… → group 4 (piju, čtu).'],['Odtrhněte -at, -et/-ět/-it nebo -ovat a přidejte koncovky skupiny: děl-at → děl-ám, děl-áš, děl-á…','Take off -at, -et/-ět/-it or -ovat and add the group’s endings: děl-at → děl-ám, děl-áš, děl-á…'],['Ve 4. skupině se mění celé slovo: naučte se tvar já (číst → čtu, pít → piju). Ostatní tvary z něj snadno odvodíte.','In group 4 the word itself changes: learn the I form (číst → čtu, pít → piju). The other forms follow easily from it.']],
  watch:[['Dokonavá slovesa nemají přítomný čas: udělám = udělám to (v budoucnu).','Perfective verbs have no present tense: udělám = I will do it.']],example:'dělat',extra:'groups'},
 Past:{title:['Minulý čas','Past tense'],formula:['minulý tvar (-l, -la, -lo, -li) + jsem · jsi · — · jsme · jste · —','past form (-l, -la, -lo, -li) + jsem · jsi · — · jsme · jste · —'],
  steps:[['Z infinitivu odstraňte -t a přidejte -l: dělat → dělal, mluvit → mluvil, psát → psal.','Drop the -t of the infinitive and add -l: dělat → dělal, mluvit → mluvil, psát → psal.'],['Koncovka podle rodu: muž -l, žena -la, střední rod -lo, množné číslo -li (jen ženy -ly).','The ending shows gender: man -l, woman -la, neuter -lo, plural -li (women only: -ly).'],['Přidejte jsem, jsi, jsme, jste. Ve 3. osobě se nepřidává nic: on dělal, oni dělali.','Add jsem, jsi, jsme, jste. The 3rd person adds nothing: on dělal, oni dělali.']],
  watch:[['Nepravidelné: být → byl, jít → šel, jíst → jedl, číst → četl, moct → mohl, říct → řekl.','Irregular: být → byl, jít → šel, jíst → jedl, číst → četl, moct → mohl, říct → řekl.'],['Zvratná slovesa: díval jsem se; ty: díval ses (= díval jsi se).','Reflexive verbs: díval jsem se; for ty: díval ses (= díval jsi se).'],['Slovosled: jsem, jsi… stojí na 2. místě, před se/si a zájmeny: Včera jsem se mu omluvil. (Pravidla → Slovosled)','Word order: jsem, jsi… stand in the 2nd position, before se/si and pronouns: Včera jsem se mu omluvil. (Rules → Word order)']],example:'dělat',extra:'nout'},
 Future:{title:['Budoucí čas','Future tense'],formula:['nedokonavé: budu + infinitiv · dokonavé: tvar přítomného času','imperfective: budu + infinitive · perfective: the present-tense form'],
  steps:[['Zjistěte vid slovesa (viz Vid níže).','Check the verb’s aspect (see Aspect below).'],['Nedokonavé: budu, budeš, bude, budeme, budete, budou + infinitiv → budu dělat.','Imperfective: budu, budeš, bude, budeme, budete, budou + infinitive → budu dělat.'],['Dokonavé: časujte jako v přítomném čase, význam je budoucí → udělám.','Perfective: conjugate it like the present; the meaning is future → udělám (I will do it and finish).']],
  watch:[['Nikdy budu + dokonavé sloveso (ne „budu udělat“).','Never budu + a perfective verb (not “budu udělat”).'],['Zvláštní tvary: být → budu, jít → půjdu, jet → pojedu (víc u sloves pohybu níže).','Special forms: být → budu, jít → půjdu, jet → pojedu (more under verbs of motion below).']],example:'dělat|udělat'},
 Conditional:{title:['Podmiňovací způsob','Conditional'],formula:['minulý tvar + bych · bys · by · bychom · byste · by','past form + bych · bys · by · bychom · byste · by'],
  steps:[['Vezměte minulý tvar: dělal, dělala, dělali.','Take the past form: dělal, dělala, dělali.'],['Přidejte bych, bys, by, bychom, byste, by.','Add bych, bys, by, bychom, byste, by.'],['Použití: zdvořilá prosba (Chtěl bych kávu.), přání (Rád bych jel do Prahy.), podmínka (Kdybych měl čas, …).','Use it for polite requests (Chtěl bych kávu. = I would like a coffee.), wishes (Rád bych jel do Prahy. = I would like to go to Prague.) and conditions (Kdybych měl čas, … = If I had time, …).']],
  watch:[['Zvratná slovesa: díval bych se; ty: díval by ses.','Reflexive verbs: díval bych se; for ty: díval by ses.'],['Po kdy- a a- se pomocné sloveso spojí do jednoho slova: kdybych, abys… (tabulka níže).','After kdy- and a- the helper joins into one word: kdybych, abys… (table below).'],['Slovosled: bych, bys… stojí na 2. místě, před se/si a zájmeny: Rád bych si to koupil. (Pravidla → Slovosled)','Word order: bych, bys… stand in the 2nd position, before se/si and pronouns: Rád bych si to koupil. (Rules → Word order)']],example:'dělat',extra:'kdy'},
 Imperative:{title:['Rozkazovací způsob','Imperative'],formula:['tvar oni bez koncovky → ty · + -te → vy · + -me → my','the oni form minus its ending → ty · + -te → vy · + -me → my'],
  steps:[['Vezměte tvar oni a odtrhněte koncovku (-ají, -í, -ou, -ujou/-ují).','Take the oni form and take off its ending (-ají, -í, -ou, -ujou/-ují).'],['Zbude jedna souhláska → hotovo: mluv-í → mluv, pracuj-ou → pracuj. Po -ají přidejte -ej: děl-ají → dělej.','One consonant left → done: mluv-í → mluv, pracuj-ou → pracuj. After -ají add -ej: děl-ají → dělej.'],['Zbudou dvě souhlásky → přidejte -i: čt-ou → čti, sp-í → spi.','Two consonants left → add -i: čt-ou → čti, sp-í → spi.'],['Pro vy přidejte -te (po -i je to -ěte: čtěte, spěte), pro my -me.','For vy add -te (after -i it becomes -ěte: čtěte, spěte); for my (let’s) add -me.']],
  watch:[['Dlouhá samohláska se často zkrátí: píšou → piš, koupí → kup. D, t, n na konci změknou: sedí → seď, platí → plať.','A long vowel often gets shorter: píšou → piš, koupí → kup. A final d, t, n becomes soft: sedí → seď, platí → plať.'],['Nepravidelné: být → buď, jíst → jez, vědět → věz, jít → jdi / pojď.','Irregular: být → buď, jíst → jez, vědět → věz, jít → jdi / pojď.']],example:null,extra:'imp'}
};
const IMP_ROWS=[['dělají','děl- + ej','dělej','dělejte','dělejme'],['mluví','mluv-','mluv','mluvte','mluvme'],['pracujou (pracují)','pracuj-','pracuj','pracujte','pracujme'],['čtou','čt- + i','čti','čtěte','čtěme'],['spí','sp- + i','spi','spěte','spěme'],['píšou','píš- → piš','piš','pište','pišme']];
const GROUP_ROWS=[
 ['1 · -á','-at','dělat → dělám',[['mít → mám','mít (to have) → mám']],['mít má -ít, ale časuje se jako dělat: mám, máš, má…','mít ends in -ít but conjugates like dělat: mám, máš, má…']],
 ['2 · -í','-et, -ět, -it','mluvit → mluvím · rozumět → rozumím',[['jíst → jím','jíst (to eat) → jím'],['spát → spím','spát (to sleep) → spím'],['stát → stojím','stát (to stand) → stojím']],['Podle infinitivu by patřila jinam, ale časují se jako mluvit: jím, jíš…; spím, spíš…; stojím, stojíš…','By their infinitive they should belong elsewhere, but they conjugate like mluvit: jím, jíš…; spím, spíš…; stojím, stojíš…']],
 ['3 · -uj','-ovat','pracovat → pracuju',[],['Žádné výjimky — nejpravidelnější skupina!','No exceptions — the most regular group!']],
 ['4 · -e','-ít, -ýt, -ét, -íst, -ést, -ást, -ůst','číst → čtu · pít → piju',[['psát → píšu','psát (to write) → píšu'],['brát → beru','brát (to take) → beru'],['chtít → chci','chtít (to want) → chci']],['Tady se mění celé slovo — tvar já se učte nazpaměť. Patří sem i některá slovesa na -at (psát, brát).','Here the word itself changes — learn the I form by heart. Some -at verbs belong here too (psát, brát).']]
];
function extraHTML(key){
 if(key==='groups')return `<div class="table-wrap"><table class="conj grp-ex"><thead><tr><th>${esc(B('Skupina','Group'))}</th><th>${esc(B('Infinitiv','Infinitive'))}</th><th>${esc(B('Příklad','Example'))}</th><th>${esc(B('Výjimky','Exceptions'))}</th></tr></thead><tbody>${GROUP_ROWS.map(([g,inf,ex,exc,note])=>`<tr><th>${esc(g)}</th><td class="muted">${esc(inf)}</td><td>${esc(ex)}</td><td class="exc">${exc.length?exc.map(e=>`<b>${esc(isEasy()?e[1]:e[0])}</b>`).join('<br>'):'—'}<span class="exc-note">${tx(note)}</span></td></tr>`).join('')}</tbody></table></div>`;
 if(key==='imp')return `<div class="table-wrap"><table class="conj imp"><thead><tr><th>oni</th><th>${esc(B('bez koncovky','minus ending'))}</th><th>ty</th><th>vy</th><th>my</th></tr></thead><tbody>${IMP_ROWS.map(r=>`<tr><td class="from">${esc(r[0])}</td><td class="muted">${esc(r[1])}</td><td>${esc(r[2])}</td><td>${esc(r[3])}</td><td>${esc(r[4])}</td></tr>`).join('')}</tbody></table></div>`;
 if(key==='kdy'){const rows=[['já','bych','kdybych','abych'],['ty','bys','kdybys','abys'],['on / ona / ono','by','kdyby','aby'],['my','bychom','kdybychom','abychom'],['vy','byste','kdybyste','abyste'],['oni / ony','by','kdyby','aby']];
  return `<div class="sub-box"><h4>${esc(B('Kdy- a a- + bych = jedno slovo','kdy- and a- + bych = one word'))}</h4>
  <p>${T('Spojky <strong>kdyby</strong> (podmínka) a <strong>aby</strong> (účel, přání) v sobě už mají pomocné sloveso. Proto se nepíše „kdy bych“ ani „když bych“, ale jedno slovo, které se mění podle osoby: <strong>kdybych, kdybys, kdyby…</strong> a <strong>abych, abys, aby…</strong> Za ním už následuje jen tvar na -l.','The conjunctions <strong>kdyby</strong> (if) and <strong>aby</strong> (so that / that) already contain the helper. So you do not write “kdy bych” or “když bych” but one word that changes with the person: <strong>kdybych, kdybys, kdyby…</strong> and <strong>abych, abys, aby…</strong> After it comes only the -l form.')}</p>
  <div class="table-wrap"><table class="conj"><thead><tr><th></th><th>${esc(B('pomocné','helper'))}</th><th>${esc(B('kdy- (podmínka)','kdy- (if)'))}</th><th>${esc(B('a- (účel, přání)','a- (so that, wish)'))}</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${esc(r[0])}</th><td>${esc(r[1])}</td><td><b>${esc(r[2])}</b></td><td><b>${esc(r[3])}</b></td></tr>`).join('')}</tbody></table></div>
  <p class="ex">${T('<strong>Kdybys</strong> měl čas, zavolej. · <strong>Kdybychom</strong> věděli, přišli bychom. · Chci, <strong>abys</strong> mi pomohl. · Řekni mu, <strong>aby</strong> přišel. · Učím se, <strong>abych</strong> našel práci.','<strong>Kdybys</strong> měl čas, zavolej. (If you had time, call.) · <strong>Kdybychom</strong> věděli, přišli bychom. (If we had known, we would have come.) · Chci, <strong>abys</strong> mi pomohl. (I want you to help me.) · Řekni mu, <strong>aby</strong> přišel. (Tell him to come.) · Učím se, <strong>abych</strong> našel práci. (I study so that I find a job.)')}</p>
  <p>${T('<strong>Se a si u ty:</strong> kdybys + se → <strong>kdyby ses</strong>, abys + si → <strong>aby sis</strong>: Kdyby ses učil… · Řekl jsem ti, aby sis odpočinul.','<strong>Se and si with ty:</strong> kdybys + se → <strong>kdyby ses</strong>, abys + si → <strong>aby sis</strong>: Kdyby ses učil… (If you studied…) · Řekl jsem ti, aby sis odpočinul. (I told you to have a rest.)')}</p>
  <p>${T('<strong>Po jiných slovech</strong> (co, kdo, jak, kde, proč, že…) se pomocné sloveso vyslovuje dohromady, ale <strong>píše se zvlášť</strong>: co bys chtěl? · kdo by to řekl · jak bychom to udělali · že bys přišel.','<strong>After other words</strong> (co, kdo, jak, kde, proč, že…) the helper is pronounced together with the word but <strong>written separately</strong>: co bys chtěl? (what would you like?) · kdo by to řekl (who would have said that) · jak bychom to udělali (how would we do it) · že bys přišel (that you would come).')}</p>
  <p>${T('Hovorově se říká i <strong>bysme, kdybysme, abysme</strong> místo bychom, kdybychom, abychom.','In everyday speech you also hear <strong>bysme, kdybysme, abysme</strong> instead of bychom, kdybychom, abychom.')}</p></div>`;}
 if(key==='nout'){const rows=[['já','rozhodnu se','rozhodl / rozhodla jsem se'],['ty','rozhodneš se','rozhodl / rozhodla ses'],['on / ona / ono','rozhodne se','rozhodl / rozhodla / rozhodlo se'],['my','rozhodneme se','rozhodli jsme se'],['vy','rozhodnete se','rozhodli jste se'],['oni / ony','rozhodnou se','rozhodli / rozhodly se']];
  return `<div class="sub-box"><h4>${esc(B('Slovesa na -nout','Verbs ending in -nout'))}</h4>
  <p>${T('Slovesa na -nout jsou téměř vždy <strong>dokonavá</strong> — jedna rychlá nebo dokončená akce: rozhodnout se, spadnout, sednout si, lehnout si, obléknout se. Časují se jako 4. skupina: -nu, -neš, -ne… a tyto tvary znamenají budoucnost.','Verbs ending in -nout are almost always <strong>perfective</strong> — one quick or completed action: rozhodnout se (to decide), spadnout (to fall), sednout si (to sit down), lehnout si (to lie down), obléknout se (to get dressed). They conjugate like group 4: -nu, -neš, -ne… and these forms mean future.')}</p>
  <p>${T('<strong>Minulý čas:</strong> když je před -nout souhláska, -nout odpadne: rozhod-nout → rozhodl, spad-nout → spadl, sed-nout → sedl. Když je před ním samohláska, zůstane -nul: mi-nout → minul, odpoči-nout si → odpočinul si. V mluvené češtině uslyšíte i spadnul, rozhodnul.','<strong>Past:</strong> if there is a consonant before -nout, -nout drops: rozhod-nout → rozhodl, spad-nout → spadl, sed-nout → sedl. If there is a vowel before it, -nul stays: mi-nout → minul (missed), odpoči-nout si → odpočinul si (rested). In spoken Czech you also hear spadnul, rozhodnul.')}</p>
  <div class="table-wrap"><table class="conj"><thead><tr><th>rozhodnout se</th><th>${esc(B('budoucnost (dokonavé)','future (perfective)'))}</th><th>${esc(B('minulost','past'))}</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${esc(r[0])}</th><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join('')}</tbody></table></div>
  <p class="ex">spadnout: spadnu, spadneš, spadne… · spadl, spadla, spadlo, spadli</p>
  <p class="watch">⚠ ${T('Vzácné nedokonavé výjimky: tisknout (tisknout dokument), mrznout. Nepravidelné: zapomenout → zapomněl.','Rare imperfective exceptions: tisknout (to print), mrznout (to freeze). Irregular: zapomenout → zapomněl (forgot).')}</p></div>`;}
 return '';}
function formCard(key,withExample=true){const f=FORM[key];let ex='';
 if(withExample&&f.example&&verbs.length){const [a,b]=f.example.split('|').map(n=>verbs.find(v=>v.verb===n));
  if(b){const ra=conj(a,key).rows,rb=conj(b,key).rows;ex=`<table class="conj"><thead><tr><th></th><th>${esc(a.verb)} <small>${esc(B('nedokonavé','imperfective'))}</small></th><th>${esc(b.verb)} <small>${esc(B('dokonavé','perfective'))}</small></th></tr></thead><tbody>${ra.map((r,i)=>`<tr><th>${esc(r[0])}</th><td>${r[2]}</td><td>${rb[i][2]}</td></tr>`).join('')}</tbody></table>`;}
  else ex=`<p class="ex-label">${esc(B('Příklad','Example'))}: <strong>${esc(a.verb)}</strong></p>`+`<table class="conj"><tbody>${conj(a,key).rows.map(([cz,en,form])=>`<tr><th>${esc(cz)}${isEasy()?` <small>${esc(en)}</small>`:''}</th><td>${form}</td></tr>`).join('')}</tbody></table>`;}
 const extra=f.extra&&(withExample||f.extra!=='nout')?extraHTML(f.extra):'';
 return `<div class="formula">${tx(f.formula)}</div><ol class="form-steps">${f.steps.map(s=>`<li>${tx(s)}</li>`).join('')}</ol>${ex}${f.watch.map(w=>`<p class="watch">⚠ ${tx(w)}</p>`).join('')}${extra}`;}

/* ---------- Rules page ---------- */
const ENDINGS=[
 ['já','I','-m / -u / -i','dělám, mluvím, čtu, piju',['Tři možnosti podle skupiny — viz tabulka skupin.','Three possibilities, depending on the group — see the groups table.']],
 ['ty','you','-š','děláš, mluvíš, čteš, piješ',['Vždy končí na -š. Jediná výjimka: být → jsi (v mluvené češtině uslyšíte jseš nebo seš).','Always ends in -š. The only exception: být → jsi (in spoken Czech you will hear jseš or seš).']],
 ['on / ona / ono','he / she / it','—','dělá, mluví, čte, pije',['Nejkratší tvar — nemá žádnou koncovku osoby.','The shortest form — it has no personal ending.']],
 ['my','we','-me','děláme, mluvíme, čteme, jsme',['Vždy -me.','Always -me.']],
 ['vy','you (plural / polite)','-te','děláte, mluvíte, čtete, jste',['Vždy -te. Pro více lidí i pro jednu osobu, které vykáte.','Always -te. For several people, and for one person you address formally.']],
 ['oni / ony','they','-ají / -í / -ou','dělají, mluví, čtou, pijou',['Podle skupiny: -ají, -í (-ějí), -ujou (-ují), -ou (-í).','Depends on the group: -ají, -í (-ějí), -ujou (-ují), -ou (-í).']]
];
const TYPES=[
 {name:['1 · -á slovesa','1 · -á verbs'],rule:['infinitiv na -at (kromě -ovat) + mít','infinitive in -at (except -ovat) + mít (to have)'],verb:'dělat',en:'to do',f:['děl[ám]','děl[áš]','děl[á]','děl[áme]','děl[áte]','děl[ají]']},
 {name:['2 · -í slovesa','2 · -í verbs'],rule:['infinitiv na -et, -ět, -it + jíst, spát, stát','infinitive in -et, -ět, -it + jíst (to eat), spát (to sleep), stát (to stand)'],verb:'rozumět',en:'to understand',f:['rozum[ím]','rozum[íš]','rozum[í]','rozum[íme]','rozum[íte]','rozum[í] (rozum[ějí])']},
 {name:['3 · -uj slovesa','3 · -uj verbs'],rule:['infinitiv na -ovat','infinitive in -ovat'],verb:'pracovat',en:'to work',f:['prac[uju] (prac[uji])','prac[uješ]','prac[uje]','prac[ujeme]','prac[ujete]','prac[ujou] (prac[ují])']},
 {name:['4 · -e slovesa','4 · -e verbs'],rule:['infinitiv na -ít, -ýt, -ét, -íst, -ést, -ást, -ůst; mění se slovo','infinitive in -ít, -ýt, -ét, -íst, -ést, -ást, -ůst; the word changes'],verb:'číst · pít',en:'to read · to drink',f:['čt[u] · pij[u] (pij[i])','čt[eš] · pij[eš]','čt[e] · pij[e]','čt[eme] · pij[eme]','čt[ete] · pij[ete]','čt[ou] · pij[ou] (pij[í])']}
];
const hl=s=>esc(s).replace(/\[(.+?)\]/g,'<b class="end">$1</b>');
const PAIRS_A=[['u-',[['dělat','udělat','to make, do'],['vidět','uvidět','to see'],['vařit','uvařit','to cook, boil'],['mýt (se)','umýt (se)','to wash (oneself)']]],['po-',[['dívat se','podívat se','to look at'],['děkovat','poděkovat','to thank'],['znát','poznat','to know; to get to know'],['čekat','počkat','to wait']]],['na-',[['psát','napsat','to write'],['snídat','nasnídat se','to have breakfast'],['obědvat','naobědvat se','to have lunch'],['večeřet','navečeřet se','to have dinner']]],['pře-',[['číst','přečíst','to read']]],['při-',[['vítat','přivítat','to welcome'],['jít','přijít','to go → to come']]],['s-',[['končit','skončit','to finish'],['jíst','sníst','to eat (up)']]],['vy-',[['pít','vypít','to drink (up)'],['čistit','vyčistit','to clean']]],['z-',[['opakovat','zopakovat','to repeat']]],['za-',[['platit','zaplatit','to pay'],['hrát','zahrát','to play'],['telefonovat','zatelefonovat','to phone']]],['ze-',[['ptát se','zeptat se','to ask']]]];
const PAIRS_B=[[['-ovat → -it','-ovat → -it'],[['kupovat','koupit','to buy'],['nastupovat','nastoupit','to get on'],['vystupovat','vystoupit','to get off / out'],['přestupovat','přestoupit','to change (trains)'],['opravovat','opravit','to repair, correct'],['vysvětlovat','vysvětlit','to explain'],['navštěvovat','navštívit','to visit']]],[['-at, -et → -nout','-at, -et → -nout'],[['oblékat se','obléknout se','to get dressed'],['svlékat se','svléknout se','to get undressed'],['prohlížet si','prohlédnout si','to look round, view'],['vzpomínat','vzpomenout si','to remember'],['zapomínat','zapomenout','to forget'],['odpočívat','odpočinout si','to rest'],['zahýbat','zahnout','to turn'],['poslouchat','poslechnout si','to listen to']]],[['-ávat → -át, -at','-ávat → -át, -at'],[['dávat','dát','to give'],['prodávat','prodat','to sell'],['dostávat','dostat','to get'],['vstávat','vstát','to get up'],['zůstávat','zůstat','to stay']]],[['nepravidelné změny','irregular changes'],[['vracet se','vrátit se','to come back'],['uklízet','uklidit','to tidy up'],['ukazovat','ukázat','to show'],['začínat','začít','to begin'],['vybírat (si)','vybrat (si)','to choose'],['odpovídat','odpovědět','to answer'],['říkat','říct','to say'],['brát','vzít','to take']]]];
function pairTable(groups,prefixMode){return `<div class="table-wrap"><table class="pairs"><thead><tr><th>${esc(B('nedokonavé','imperfective'))}</th><th>${esc(B('dokonavé','perfective'))}</th>${isEasy()?`<th>${esc(B('význam','meaning'))}</th>`:''}</tr></thead><tbody>${groups.map(([label,rows])=>{const lab=Array.isArray(label)?B(...label):label;const pre=prefixMode?label.replace('-',''):'';
 return `<tr class="grp"><th colspan="3">${esc(lab)}</th></tr>`+rows.map(([i,p,en])=>`<tr><td>${esc(i)}</td><td class="pf">${pre&&p.startsWith(pre)?'<b>'+esc(pre)+'</b>'+esc(p.slice(pre.length)):esc(p)}</td>${isEasy()?`<td class="muted">${esc(en)}</td>`:''}</tr>`).join('');}).join('')}</tbody></table></div>`;}
function exList(arr){return `<ul class="ex-list">${arr.map(([c,e])=>`<li>${esc(c)}${isEasy()?` <span class="tr">— ${esc(e)}</span>`:''}</li>`).join('')}</ul>`;}
const ASPECT_RULES=[
 [['Předpona může změnit i význam','A prefix can also change the meaning'],['Některé předpony mění význam: jít → přijít, psát → přepsat. K takovému slovesu pak vznikne nové nedokonavé s delší příponou: přepsat → přepisovat.','Some prefixes change the meaning: jít (to go) → přijít (to come), psát (to write) → přepsat (to rewrite). Such a verb then gets a new, longer imperfective: přepsat → přepisovat.'],[['Přijdu v sedm.','I will come at seven.'],['Přepíšu ten text.','I will rewrite that text.']]],
 [['Dokonavé nemá přítomný čas','Perfective has no present tense'],['„Přítomný“ tvar dokonavého slovesa znamená budoucnost. Proto nikdy budu + dokonavé (ne „budu napsat“).','The “present” form of a perfective verb means future. So never budu + a perfective verb (not “budu napsat”).'],[['napíšu','I will write (and finish)'],['koupím','I will buy'],['budu psát','I will write / be writing']]],
 [['Signální slova','Signal words'],['Nedokonavé: každý den, často, vždycky, obvykle, pořád, dlouho. Dokonavé: konečně, hned, za hodinu, celý.','Imperfective: každý den, často, vždycky, obvykle, pořád, dlouho (every day, often, always, usually, all the time, for a long time). Perfective: konečně, hned, za hodinu, celý (finally, right away, within an hour, the whole).'],[['Každý den píšu e-maily.','I write emails every day.'],['Konečně jsem napsal ten dopis.','I finally wrote that letter.']]],
 [['Po začít / přestat jen nedokonavé','After začít / přestat: imperfective only'],['Po slovesech začít, začínat, přestat a končit následuje nedokonavý infinitiv.','Verbs like začít, začínat, přestat and končit are followed by an imperfective infinitive.'],[['Začnu pracovat.','I will start working.'],['Přestal kouřit.','He stopped smoking.']]],
 [['Rozkazy','Commands'],['Kladný rozkaz bývá dokonavý, záporný bývá nedokonavý.','Positive commands are often perfective; negative commands are usually imperfective.'],[['Zavolej mi!','Call me!'],['Nevolej mi!','Don’t call me!'],['Zavři okno!','Close the window!'],['Nezavírej okno!','Don’t close the window!']]]
];
