renderGuide=function(){
 $('guide-title').textContent=B('Pravidla: jak se tvoří časy a způsoby','Rules: how to form tenses and moods');
 const sections=[['rules-endings',B('Koncovky a skupiny','Endings & groups')],['rules-forms',B('Jak se tvoří','How to form')],['rules-aspect',B('Vid','Aspect')],['rules-motion',B('Slovesa pohybu','Verbs of motion')],['rules-order',B('Slovosled','Word order')]];
 const asp=a=>a==='pf'?B('dok.','pf'):B('ned.','impf');
 $('guide-content').innerHTML=`<div class="rule-nav">${sections.map(([id,l])=>`<button type="button" data-jump="${id}">${esc(l)}</button>`).join('')}</div>
 <article class="rule-card" id="rules-endings"><h3>${esc(B('Koncovky, na které se můžete spolehnout (přítomný čas)','Endings you can rely on (present tense)'))}</h3>
  <div class="table-wrap"><table class="endings"><thead><tr><th>${esc(B('Osoba','Person'))}</th><th>${esc(B('Koncovka','Ending'))}</th><th>${esc(B('Příklady','Examples'))}</th><th>${esc(B('Pravidlo','Rule'))}</th></tr></thead><tbody>${ENDINGS.map(([cz,en,end,ex,rule])=>`<tr><th>${esc(cz)}${isEasy()?` <small>${esc(en)}</small>`:''}</th><td class="ending">${esc(end)}</td><td>${esc(ex)}</td><td>${tx(rule)}</td></tr>`).join('')}</tbody></table></div>
  <p class="tip">💡 ${T('<strong>Trik:</strong> vezměte tvar on/ona a přidejte -š, -me, -te: dělá → děláš, děláme, děláte · čte → čteš, čteme, čtete · může → můžeš, můžeme, můžete. Platí pro všechna slovesa v trenažéru kromě být.','<strong>Trick:</strong> take the on/ona form and add -š, -me, -te: dělá → děláš, děláme, děláte · čte → čteš, čteme, čtete · může → můžeš, můžeme, můžete. It works for every verb in this trainer except být.')}</p>
  <h4 class="sub-h">${esc(B('Čtyři skupiny — poznáte je podle infinitivu','The four groups — you can tell them from the infinitive'))}</h4>
  <div class="table-wrap"><table class="types"><thead><tr><th></th>${TYPES.map(t=>`<th>${esc(B(...t.name))}<span class="rule-small">${esc(B(...t.rule))}</span></th>`).join('')}</tr><tr class="verbs"><th></th>${TYPES.map(t=>`<td><strong>${esc(t.verb)}</strong>${isEasy()?` <small>${esc(t.en)}</small>`:''}</td>`).join('')}</tr></thead><tbody>${PERSONS.map((p,i)=>`<tr><th>${esc(p[0])}</th>${TYPES.map(t=>`<td>${hl(t.f[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
  <p class="conj-note">${T('Tvary v závorkách se používají jen v psané a formální češtině. V běžné řeči uslyšíte pracuju, pracujou, piju, pijou.','Forms in brackets are only used in written and formal Czech. In everyday speech you will hear pracuju, pracujou, piju, pijou.')}</p>
  <p class="tip">🧠 ${T('<strong>Nepravidelná slovesa</strong> najdete hlavně ve 4. skupině. Tam se mění celé slovo (pít → piju, číst → čtu, psát → píšu, brát → beru, chtít → chci), takže se naučte <strong>infinitiv + tvar já</strong>. Být (jsem, jsi, je…) je úplně samo pro sebe. Proč jsou ve všech jazycích nejčastější slovesa nepravidelná? Protože je používáme nejvíc — a lidé jsou kreativní!','<strong>Irregular verbs</strong> are mostly in group 4. There the word itself changes (pít → piju, číst → čtu, psát → píšu, brát → beru, chtít → chci), so learn the <strong>infinitive + the I form</strong> together. Být (jsem, jsi, je…) is a category of its own. Why are the most common verbs irregular in every language? Because we use them the most — and people are creative!')}</p></article>
 <section id="rules-forms"><h3 class="rules-h">${esc(B('Jak se tvoří časy a způsoby','How to form the tenses and moods'))}</h3>
  ${Object.keys(FORM).map(k=>`<article class="rule-card form-card${FORM[k].extra||k==='Present'?' wide':''}"><h3>${esc(B(...FORM[k].title))}</h3>${formCard(k)}</article>`).join('')}</section>
 <article class="rule-card" id="rules-aspect"><h3>${esc(B('Vid: nedokonavé × dokonavé','Aspect: imperfective × perfective'))}</h3>
  <p>${T('Většina sloves má dvojici: <strong>nedokonavé</strong> sloveso (průběh, opakování, zvyk) a <strong>dokonavé</strong> sloveso (jedna dokončená akce, výsledek). Dokonavé sloveso se tvoří dvěma způsoby:','Most verbs come in pairs: an <strong>imperfective</strong> verb (process, repetition, habit) and a <strong>perfective</strong> verb (one completed action, a result). There are two ways to form the perfective verb:')}</p>
  <div class="aspect-grid"><div><h4 class="sub-h">A · ${esc(B('Předponou','With a prefix'))}</h4><p>${T('Sloveso s předponou je <strong>dokonavé</strong>. Předpona často vypadá jako předložka (u, po, na, při, s, z, za…). Neexistuje pravidlo, která předpona patří ke kterému slovesu — dvojice se učte spolu.','The verb with the prefix is <strong>perfective</strong>. The prefix often looks like a preposition (u, po, na, při, s, z, za…). There is no rule for which prefix goes with which verb — learn the pairs together.')}</p>${pairTable(PAIRS_A,true)}</div>
  <div><h4 class="sub-h">B · ${esc(B('Změnou přípony','By changing the suffix'))}</h4><p>${T('Když se dvojice liší příponou, je <strong>delší sloveso nedokonavé</strong> (-ovat, -ávat, -at/-et) a <strong>kratší dokonavé</strong> (-it, -át, -nout). Proto jsou slovesa na -nout skoro vždy dokonavá. Poslední skupinu (nepravidelné změny) se naučte nazpaměť.','When the pair differs in the suffix, <strong>the longer verb is imperfective</strong> (-ovat, -ávat, -at/-et) and <strong>the shorter one perfective</strong> (-it, -át, -nout). That is why -nout verbs are almost always perfective. Learn the last group (irregular changes) by heart.')}</p>${pairTable(PAIRS_B,false)}</div></div>
  <ol class="aspect-rules">${ASPECT_RULES.map(([t,d,ex])=>`<li><strong>${tx(t)}</strong><p>${tx(d)}</p>${exList(ex)}</li>`).join('')}</ol>
  <div class="table-wrap"><table><thead><tr><th>${esc(B('Čas','Tense'))}</th><th>${esc(B('Nedokonavé: průběh / opakování','Imperfective: process / repetition'))}</th><th>${esc(B('Dokonavé: celek / výsledek','Perfective: whole event / result'))}</th></tr></thead><tbody><tr><td>${esc(B('Minulost','Past'))}</td><td>Včera jsem psala dopis.${isEasy()?'<span class="en">Yesterday I was writing / wrote a letter (completion not stated).</span>':''}</td><td>Včera jsem napsala dopis.${isEasy()?'<span class="en">Yesterday I wrote (and finished) a letter.</span>':''}</td></tr><tr><td>${esc(B('Budoucnost','Future'))}</td><td>Zítra budu psát dopis.${isEasy()?'<span class="en">Tomorrow I will write / be writing a letter.</span>':''}</td><td>Zítra napíšu dopis.${isEasy()?'<span class="en">Tomorrow I will write (and finish) a letter.</span>':''}</td></tr></tbody></table></div>
  <p class="watch">⚠ ${T('Český vid není totéž co anglické simple/progressive: píšu může znamenat I write i I am writing.','Czech aspect is not the same as English simple/progressive: píšu can mean both I write and I am writing.')}</p></article>
 <article class="rule-card" id="rules-motion"><h3>${esc(B('Slovesa pohybu','Verbs of motion'))}</h3>
  <p>${T('U pohybu má čeština <strong>dvě nedokonavá slovesa</strong>: jedno pro <strong>jeden směr, právě teď</strong> (jít, jet, letět, nést, vést, vézt, běžet) a druhé pro <strong>opakovaný pohyb</strong> nebo pohyb bez jednoho směru (chodit, jezdit, létat, nosit, vodit, vozit, běhat).','For motion, Czech has <strong>two imperfective verbs</strong>: one for <strong>a single direction, right now</strong> (jít, jet, letět, nést, vést, vézt, běžet) and one for <strong>repeated movement</strong> or movement in no single direction (chodit, jezdit, létat, nosit, vodit, vozit, běhat).')}</p>
  <ul class="form-steps"><li>${T('<strong>Budoucnost:</strong> sloveso jednoho směru dostane pů-/po-: půjde, pojede, poletí, ponese, povede, poveze, poběží. Sloveso opakovaného pohybu má bude + infinitiv: bude chodit.','<strong>Future:</strong> the one-direction verb takes pů-/po-: půjde, pojede, poletí, ponese, povede, poveze, poběží. The repeated-motion verb uses bude + infinitive: bude chodit.')}</li>
  <li>${T('<strong>Předpona při- (příchod):</strong> ze slovesa jednoho směru vznikne dokonavé sloveso (přijít, přijet, přinést…), ze slovesa opakovaného pohybu jeho nedokonavý pár (přicházet, přijíždět, přinášet…).','<strong>Prefix při- (arriving):</strong> from the one-direction verb you get a perfective verb (přijít, přijet, přinést…); from the repeated-motion verb you get its imperfective partner (přicházet, přijíždět, přinášet…).')}</li></ul>
  ${exList([['Teď jdu do školy.','I’m going to school now.'],['Každý den chodím do školy.','I go to school every day.'],['Zítra pojedu do Brna.','Tomorrow I will go to Brno.'],['Přijdu v sedm.','I will come at seven.'],['Přines mi kávu, prosím.','Bring me a coffee, please.']])}
  <div class="table-wrap"><table class="motion"><thead><tr><th>${esc(B('Infinitiv','Infinitive'))}</th><th>${esc(B('Vid','Aspect'))}</th><th>${esc(B('Přítomný (on/ona)','Present (he/she)'))}</th><th>${esc(B('Minulý','Past'))}</th><th>${esc(B('Budoucí','Future'))}</th>${isEasy()?`<th>${esc(B('Význam','Meaning'))}</th>`:''}</tr></thead>${MOTION.map(pair=>`<tbody>${pair.map(r=>`<tr><td><strong>${esc(r[0])}</strong></td><td class="muted">${esc(asp(r[1]))}</td><td>${esc(r[2])}</td><td>${esc(r[3])}</td><td>${esc(r[4])}</td>${isEasy()?`<td class="muted">${esc(r[5])}</td>`:''}</tr>`).join('')}</tbody>`).join('')}</table></div></article>`;
 $('guide-content').insertAdjacentHTML('beforeend',wordOrderHTML());
 $('guide-content').querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>$(b.dataset.jump).scrollIntoView({behavior:'smooth',block:'start'}));
};

/* ---------- Rules: word order and the short words in the second position ---------- */
function wordOrderHTML(){
 const rows=[
  ['Včera','jsem','','ti','to','dal.','Yesterday I gave it to you.'],
  ['Dal','jsem','','ti','to','včera.','I gave it to you yesterday.'],
  ['Můj starší bratr','','se','mi','to','snažil vysvětlit.','My older brother tried to explain it to me.'],
  ['Včera','jsem','si','','ho','koupila.','Yesterday I bought it (for myself).'],
  ['Kdy','ses ¹','','mu','','omluvil?','When did you apologise to him?'],
  ['Koupila','bych','si','','ho.','','I would buy it (for myself).'],
  ['Vím, že','jsi','','mi','to','řekl.','I know that you told me.'],
  ['Kdybych ²','','','ti','to','řekl, …','If I told you…'],
  ['Petr','—','','mu','to','dal.','Petr gave it to him.'],
  ['Zítra','—','se','ti','','ozvu.','I’ll get in touch with you tomorrow.']];
 const head=[B('1. místo','1st position'),B('čas (jsem, bych…)','tense mark'),B('zvratné (se, si)','reflexive'),B('nepřímý předmět (3. pád)','IO (3rd case)'),B('přímý předmět (4. pád)','DO (4th case)'),B('zbytek věty','rest of the sentence')];
 return `<article class="rule-card" id="rules-order"><h3>${esc(B('Slovosled: krátká slova na 2. místě','Word order: the short words in second position'))}</h3>
  <p>${T('<strong>Základní slovosled</strong> je: podmět + sloveso + přímý předmět + nepřímý předmět: <em>Petr dal knihu Janě.</em> Tento pořádek ale narušují <strong>krátká slova</strong> (příklonky), která musí stát vždy na <strong>2. místě ve větě</strong>.','<strong>The basic word order</strong> is: subject + verb + direct object + indirect object: <em>Petr dal knihu Janě.</em> (Petr gave the book to Jana.) But this order is disturbed by <strong>short words</strong> (clitics), which must always stand in the <strong>second position in the sentence</strong>.')}</p>
  <p>${T('<strong>2. místo = za prvním větným členem, ne za prvním slovem.</strong> „Můj starší bratr“ je jeden člen, proto: <em>Můj starší bratr <b>se mi to</b> snažil vysvětlit.</em> Ve vedlejší větě je prvním členem spojka (že, když, protože…): <em>Vím, že <b>jsi mi to</b> řekl.</em>','<strong>2nd position = after the first part of the sentence, not after the first word.</strong> “Můj starší bratr” (my older brother) is one part, so: <em>Můj starší bratr <b>se mi to</b> snažil vysvětlit.</em> In a clause, the conjunction (že, když, protože…) is the first part: <em>Vím, že <b>jsi mi to</b> řekl.</em> (I know that you told me.)')}</p>
  <h4 class="sub-h">${esc(B('4 druhy krátkých slov — a jejich pořadí','4 kinds of short words — and their order'))}</h4>
  <ol class="form-steps">
   <li>${T('<strong>Znak času</strong> (minulý čas, podmiňovací způsob): jsem, jsi, jsme, jste · bych, bys, by, bychom, byste','<strong>Tense mark</strong> (past, conditional): jsem, jsi, jsme, jste · bych, bys, by, bychom, byste')}</li>
   <li>${T('<strong>Zvratné zájmeno:</strong> se, si','<strong>Reflexive pronoun:</strong> se, si')}</li>
   <li>${T('<strong>Nepřímý předmět – zájmeno ve 3. pádě:</strong> mi, ti, mu, jí, nám, vám, jim','<strong>Indirect object – pronoun in the 3rd case:</strong> mi, ti, mu, jí, nám, vám, jim')}</li>
   <li>${T('<strong>Přímý předmět – zájmeno ve 4. pádě:</strong> mě, tě, ho, ji, to, nás, vás, je','<strong>Direct object – pronoun in the 4th case:</strong> mě, tě, ho, ji, to, nás, vás, je')}</li></ol>
  <div class="formula">${esc(B('2. místo:  čas  +  se/si  +  3. pád  +  4. pád','2nd position:  tense mark  +  se/si  +  IO  +  DO'))}</div>
  <div class="table-wrap"><table class="conj word-order"><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r[0])}</td>${r.slice(1,5).map(c=>`<td class="wo-slot"><b>${esc(c)}</b></td>`).join('')}<td>${esc(r[5])}${isEasy()?`<span class="en">${esc(r[6])}</span>`:''}</td></tr>`).join('')}</tbody></table></div>
  <p class="ex">${T('¹ ty: jsi + se → <strong>ses</strong>, jsi + si → <strong>sis</strong> (Kdy ses mu omluvil? Koupil sis to?) · ² kdy- a a- se se znakem podmínky spojí do jednoho slova: kdybych, abych (viz Podmiňovací způsob).','¹ ty: jsi + se → <strong>ses</strong>, jsi + si → <strong>sis</strong> (Kdy ses mu omluvil? Koupil sis to?) · ² kdy- and a- join the conditional mark into one word: kdybych, abych (see Conditional).')}</p>
  <p class="watch">⚠ ${T('Ve 3. osobě minulého času a v přítomném a budoucím čase znak času chybí — ostatní krátká slova zůstávají na 2. místě: <em>Petr mu to dal. · Zítra se ti ozvu.</em> Pozor na rozdíl <strong>jí</strong> (3. pád: dám jí to) × <strong>ji</strong> (4. pád: vidím ji).','In the 3rd person past and in the present and future there is no tense mark — the other short words still go in the 2nd position: <em>Petr mu to dal. · Zítra se ti ozvu.</em> Watch the difference <strong>jí</strong> (3rd case: dám jí to = I’ll give it to her) × <strong>ji</strong> (4th case: vidím ji = I see her).')}</p></article>`;}

/* ---------- Practice: "How to form it" box for the current exercise ---------- */
// One card per present-tense group: explanation + full conjugation (endings in [brackets] are highlighted).
const GROUP_CARDS={
 am:{title:['1 · -á slovesa','1 · -á verbs'],
  how:['Sem patří slovesa s infinitivem na <strong>-at</strong> (kromě -ovat). Odtrhněte -at a přidejte koncovky.','This group has verbs whose infinitive ends in <strong>-at</strong> (except -ovat). Take off -at and add the endings.'],
  endings:'-ám · -áš · -á · -áme · -áte · -ají',
  verbs:[['dělat','to do',['děl[ám]','děl[áš]','děl[á]','děl[áme]','děl[áte]','děl[ají]']],['znát','to know',['zn[ám]','zn[áš]','zn[á]','zn[áme]','zn[áte]','zn[ají]']],['mít','to have',['m[ám]','m[áš]','m[á]','m[áme]','m[áte]','m[ají]'],true]],
  note:['Výjimka: <strong>mít</strong> končí na -ít, ale časuje se jako dělat.','Exception: <strong>mít</strong> ends in -ít, but it conjugates like dělat.']},
 im:{title:['2 · -í slovesa','2 · -í verbs'],
  how:['Sem patří slovesa s infinitivem na <strong>-et, -ět, -it</strong>. Odtrhněte -et/-ět/-it a přidejte koncovky.','This group has verbs whose infinitive ends in <strong>-et, -ět, -it</strong>. Take off -et/-ět/-it and add the endings.'],
  endings:'-ím · -íš · -í · -íme · -íte · -í (-ějí)',
  verbs:[['mluvit','to speak',['mluv[ím]','mluv[íš]','mluv[í]','mluv[íme]','mluv[íte]','mluv[í]']],['rozumět','to understand',['rozum[ím]','rozum[íš]','rozum[í]','rozum[íme]','rozum[íte]','rozum[í] (rozum[ějí])']],['jíst','to eat',['j[ím]','j[íš]','j[í]','j[íme]','j[íte]','jed[í]'],true],['spát','to sleep',['sp[ím]','sp[íš]','sp[í]','sp[íme]','sp[íte]','sp[í]'],true],['stát','to stand',['stoj[ím]','stoj[íš]','stoj[í]','stoj[íme]','stoj[íte]','stoj[í]'],true]],
  note:['Výjimky: <strong>jíst, spát, stát</strong> by podle infinitivu patřila jinam, ale časují se jako mluvit. Pozor: oni jedí, já stojím.','Exceptions: by their infinitive, <strong>jíst, spát, stát</strong> should belong elsewhere, but they conjugate like mluvit. Careful: oni jedí, já stojím.']},
 uji:{title:['3 · -uj slovesa','3 · -uj verbs'],
  how:['Sem patří všechna slovesa s infinitivem na <strong>-ovat</strong>. Místo -ovat dejte -uj- a koncovky.','This group has every verb whose infinitive ends in <strong>-ovat</strong>. Replace -ovat with -uj- and add the endings.'],
  endings:'-uju · -uješ · -uje · -ujeme · -ujete · -ujou',
  verbs:[['pracovat','to work',['prac[uju] (prac[uji])','prac[uješ]','prac[uje]','prac[ujeme]','prac[ujete]','prac[ujou] (prac[ují])']],['studovat','to study',['stud[uju] (stud[uji])','stud[uješ]','stud[uje]','stud[ujeme]','stud[ujete]','stud[ujou] (stud[ují])']]],
  note:['Žádné výjimky — nejpravidelnější skupina! Tvary v závorkách jsou psané a formální.','No exceptions — the most regular group! Forms in brackets are written and formal.']},
 u:{title:['4 · -e slovesa','4 · -e verbs'],
  how:['Infinitiv končí na <strong>-ít, -ýt, -ét, -íst, -ést, -ást, -ůst</strong> (a některá na -at). Mění se celé slovo, proto se naučte <strong>tvar já</strong> — ostatní tvary mají koncovky -eš, -e, -eme, -ete, -ou.','The infinitive ends in <strong>-ít, -ýt, -ét, -íst, -ést, -ást, -ůst</strong> (and some in -at). The word itself changes, so learn <strong>the I form</strong> — the other forms take -eš, -e, -eme, -ete, -ou.'],
  endings:'-u · -eš · -e · -eme · -ete · -ou',
  verbs:[['číst','to read',['čt[u]','čt[eš]','čt[e]','čt[eme]','čt[ete]','čt[ou]']],['pít','to drink',['pij[u] (pij[i])','pij[eš]','pij[e]','pij[eme]','pij[ete]','pij[ou] (pij[í])']],['psát','to write',['píš[u] (píš[i])','píš[eš]','píš[e]','píš[eme]','píš[ete]','píš[ou] (píš[í])'],true],['brát','to take',['ber[u]','ber[eš]','ber[e]','ber[eme]','ber[ete]','ber[ou]'],true],['chtít','to want',['chc[i]','chc[eš]','chc[e]','chc[eme]','chc[ete]','chtěj[í]'],true]],
  note:['Nepravidelná slovesa jsou hlavně tady: psát a brát končí na -at, chtít má chci… chtějí. Infinitiv + tvar já se učte spolu.','Most irregular verbs live here: psát and brát end in -at, chtít has chci… chtějí. Learn the infinitive + the I form together.']}
};
function groupCard(key){const g=GROUP_CARDS[key];
 return `<p>${tx(g.how)}</p><div class="formula">${esc(B('Koncovky','Endings'))}: ${esc(g.endings)}</div>
 <div class="table-wrap"><table class="types grp-full"><thead><tr><th></th>${g.verbs.map(([v,en,,exc])=>`<th>${esc(v)}${isEasy()?` <small>${esc(en)}</small>`:''}${exc?`<span class="exc-tag">${esc(B('výjimka','exception'))}</span>`:''}</th>`).join('')}</tr></thead><tbody>${PERSONS.map((p,i)=>`<tr><th>${esc(p[0])}</th>${g.verbs.map(v=>`<td>${hl(v[2][i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
 <p class="tip">💡 ${tx(g.note)}</p>`;}
let howtoOpen=false;
const showBeforeReference=show;show=function(){showBeforeReference();const h=$('howto');const lvl=current&&FORM[current.level]?current.level:null;
 h.hidden=!lvl;h.ontoggle=()=>{howtoOpen=h.open};h.open=howtoOpen;if(!lvl)return;
 const grp=$('group').value;const one=lvl==='Present'&&GROUP_CARDS[grp];
 $('howto-title').textContent=B('Jak se tvoří: ','How to form: ')+LV(lvl).toLowerCase()+(one?' · '+B(...GROUP_CARDS[grp].title):'');
 $('howto-body').innerHTML=one?groupCard(grp):formCard(lvl,false);};

$('ref-level').addEventListener('change',()=>renderDictionary());
